import { useIntl } from 'react-intl';

import { BasicContainer } from 'components';

import type { ResourceAllocationCardKey } from '../../constants';
import type { ResourceAllocationCardsData } from '../../types';
import { ConnectSection } from './ConnectSection/ConnectSection';
import { CreativeDevelopmentSection } from './CreativeDevelopmentSection/CreativeDevelopmentSection';
import { StyledSubPillarCardsGrid } from './HowWeDoIt.styles';
import { ResourceAllocationSection } from './ResourceAllocationSection/ResourceAllocationSection';

export interface HowWeDoItProps {
  isDesktopLarge: boolean;
  loading?: boolean;
  error?: unknown;
  resourceAllocationCardsData?: ResourceAllocationCardsData;
  onResourceAllocationCardClick: (key: ResourceAllocationCardKey) => void;
}

export const HowWeDoIt = ({
  isDesktopLarge,
  loading,
  error,
  resourceAllocationCardsData,
  onResourceAllocationCardClick,
}: HowWeDoItProps) => {
  const { formatMessage } = useIntl();

  return (
    <BasicContainer
      header={{
        title: formatMessage({
          id: 'ConnectionsCreativity.Home.howWeDoIt',
        }),
        titleSize: isDesktopLarge ? 'H2' : 'H3',
      }}
      layout={{
        bodyPadding: false,
        background: '#fafafa',
        border: 'gray',
      }}
    >
      <StyledSubPillarCardsGrid data-testid="sub-pillar-cards-grid">
        <ResourceAllocationSection
          isDesktopLarge={isDesktopLarge}
          loading={loading}
          error={error}
          resourceAllocationCardsData={resourceAllocationCardsData}
          onCardClick={onResourceAllocationCardClick}
        />
        <CreativeDevelopmentSection />
        <ConnectSection />
      </StyledSubPillarCardsGrid>
    </BasicContainer>
  );
};
